        Self::SUPPORTED_MAX_LORA_RANKS
            .iter()
            .map(usize::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    }
}

impl Default for Qwen3LoraOptions {
    fn default() -> Self {
        Self {
            max_loras: Self::DEFAULT_MAX_LORAS,
            max_lora_rank: Self::DEFAULT_MAX_LORA_RANK,
        }
    }
}

